// PRIMARY: networking/p2p/src/main/java/tech/pegasys/teku/networking/p2p/libp2p/gossip/GossipHandler.java:apply (lines 62-82)
// P2P message size check BEFORE SSZ deserialization (Teku's equivalent of RLP block size guard)
public SafeFuture<ValidationResult> apply(final MessageApi message) {
    messageCounter.inc();
    final int messageSize = message.getData().readableBytes();
    final int maxMessageSize = handler.getMaxMessageSize(); // MAX_PAYLOAD_SIZE from spec config
    if (messageSize > maxMessageSize) {
        LOG.trace("Rejecting gossip message of length {} which exceeds maximum size of {}",
            messageSize, maxMessageSize);
        return VALIDATION_FAILED; // Rejects before any decoding
    }
    return handler.handleMessage(gossipPubsubMessage.getPreparedMessage());
}

